<script type="text/javascript">
var comment_id = {COMMENT_ID};
ajax.callback.comments = function(data) {
    if(data.up) $('#chat').scrollTop(0);
    if(data.clear) {
        $('.chat_message').attr('value', '');
        get_message_comments(1);
    }
    <!-- IF IS_AM -->
    else if(data.del) {
