        ajax.open = false;
    } else if(data.text){
        ajax.open = data.post_id;
        $('#pe_'+ data.post_id).html(data.text);
    }
    <!-- ENDIF -->
    else {
        if(data.message) $('#chat').prepend(data.message);
        initPostBBCode('#chat');
    }

    if(data.id) comment_id = data.id;
};
setInterval(function(){ get_message_comments(0); }, 60000);

function get_message_comments(up){
    ajax.exec({action: 'comments', table: 'user', mode: 'select', id: comment_id, type_id: {PROFILE_USER_ID}, up: up});
}
function submit_click(e) {
    e = e || window.event;
    if (e.keyCode == 13 && e.ctrlKey) {
        submit_chat();
    };
}
function submit_chat(){
    var message = $('.chat_message').val();
    if (message.length < 3) {
        alert('Вы должны ввести текст сообщения');
        $('.chat_message').focus();
        return false;
    }
    ajax.exec({action : 'comments', table: 'user', type_id: {PROFILE_USER_ID}, mode: 'insert', message: message});
}
function add_nick(text){
    var message = $('.chat_message').val();
    $('.chat_message').attr('value', message + text +' ');
    $('.chat_message').focus();
}
</script>
<!-- IF IS_AM -->
<script type="text/javascript">
ajax.open = false;
function edit_comment (post_id, text, type) {
    if(ajax.open && ajax.open != post_id) {
        alert('У вас уже открыто одно быстрое редактирование!');
    } else{
        if(ajax.open && !text){
            $('#pp_'+ post_id).show();
            $('#pe_'+ post_id).hide();
        } else{
            $('#pp_'+ post_id).hide();
            $('#pe_'+ post_id).show();

            ajax.exec({
                action  : 'comments',
                mode    : 'edit',
                post_id : post_id,
                text    : text,
                type_id : {PROFILE_USER_ID},
                table   : 'user',
                type    : type
            });
        }
        ajax.open = false;
    }
}
function del_message_chat(){
    if(!confirm('Вы уверены, что хотите удалить эти сообщения?')) return false;
    var ids = 0;
    $('input.chat-post:checked').each(function(){
        ids += ','+ this.value;
    });
    if(!ids) alert('Вы не выбрали сообщения.');
    else ajax.exec({action : 'comments', table: 'user', type_id: {PROFILE_USER_ID}, mode: 'delete', ids: ids});
}
function set_hid_chbox(id)
{
    $('#pp_'+ id).toggleClass('hl-selected-post');
