function bbcode_chat ($text)
{
    global $bbcode;

    if (!isset($bbcode))
    {
        $bbcode = new bbcode();
    }
    $text = $bbcode->new_line2html($text);
    $text = $bbcode->make_clickable($text);
    $text = $bbcode->smilies_pass($text);

    return ($text);
}

